from taf.cloud.cbam.catalog.v19.catalog import Catalog19
from taf.cloud.cbam.session import CbamSession
from taf.cloud.cbam.session import CbamResponse
from test import unittest, Mock
from mock import call
from taf.cloud.cbam.exception import VnfdidPkgNotFound


class TestCatalog(unittest.TestCase):
    def setUp(self):
        self.m_client = Mock(spec=CbamSession)
        self.catalog = Catalog19(self.m_client)

    def test_getCatalogInfo_returnRightParams(self):
        self.m_client.send_request.return_value = CbamResponse(
            Mock(json=Mock(return_value=[{'id': '193', 'vnfdId': '5GBTS_VNF_VCP_1.1.13-19A'},
                                         {'id': '143', 'vnfdId': '5GBTS_vnf_NCIR17A_1.0.6-19'}]), status_code=200))

        resp = self.catalog.get_info()
        self.m_client.send_request.assert_called_with(api_version=None,
                                                      method='get',
                                                      endpoint='vnfpkgm/v1/vnf_packages')

        self.assertEqual(resp, [{'id': '193', 'vnfdId': '5GBTS_VNF_VCP_1.1.13-19A'},
                                {'id': '143', 'vnfdId': '5GBTS_vnf_NCIR17A_1.0.6-19'}])

    def test_deleteCatalogInfo_return_RightParams(self):
        self.m_client.send_request.side_effect = [CbamResponse(
            Mock(json=Mock(return_value=[{'id': '143', 'vnfdId': '5GBTS_vnf_NCIR17A_1.0.6-19'}]), status_code=204)),
            CbamResponse(Mock(json=Mock(return_value={"status_code": 204})))]

        resp = self.catalog.delete_info(vnfd_id='5GBTS_vnf_NCIR17A_1.0.6-19')
        self.assertEqual(resp, {'status_code': 204})
        self.assertEqual(self.m_client.send_request.call_count, 2)
        expected_calls = [call(api_version=None, endpoint='vnfpkgm/v1/vnf_packages', method='get'),
                          call(api_version=None, endpoint='vnfpkgm/v1/vnf_packages/143', method='delete')]
        self.m_client.send_request.assert_has_calls(expected_calls)

    def test_deleteCatalogInfo_return_WrongParams(self):
        self.m_client.send_request.side_effect = [CbamResponse(
            Mock(json=Mock(return_value=[{'id': '143', 'vnfdId': '5GBTS_vnf_NCIR17A_1.0.6-19'}]), status_code=204))]
        with self.assertRaises(VnfdidPkgNotFound):
            self.catalog.delete_info(vnfd_id='5GBTS_vnf_Not_Avilable')

    def test_postCatalogInfo_return_RightParams(self):
        self.m_client.send_request.side_effect = [CbamResponse(Mock(json=Mock(return_value={"id": 143}))),
                                                  CbamResponse(Mock(json=Mock(return_value={"status_code": 202})))]
        resp = self.catalog.post_info(cbam_catalog_zip="testzip.zip")
        self.assertEqual(self.m_client.send_request.call_count, 2)
        self.assertEqual(resp, {"status_code": 202})
        expected_calls = [call(api_version=None, endpoint='vnfpkgm/v1/vnf_packages', method='post'),
                          call(api_version=None, content_type='application/zip', data='testzip.zip',
                               endpoint='vnfpkgm/v1/vnf_packages/143/package_content', method='put')]
        self.m_client.send_request.assert_has_calls(expected_calls)
